// ***************
// Filename: npu_top.sv
// Author: FPGA Cores 4 U
// Description: npu with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map npu_regs (u_regs,
//   src/include/npu_regs.sv, ID "NPU8", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic npu (u_core, src/npu.sv), joined by
//   the register interface npu_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from npu_regs.json and the ports of npu:
//   regenerate after changing either. Clock - clk. Reset - synchronous active
//   low rst_n.
// Date: 2026-10-26
module npu_top #(
  parameter int ADDR_W = 32,                        // AXI byte address bits
  parameter int ID_W = 4,                           // AXI ID bits
  parameter int PE_P = 64,                          // MAC array: output pixels per strip
  parameter int PE_O = 64                           // MAC array: output channels per tile
) (
  input  logic clk,                                 // clock
  input  logic rst_n,                               // synchronous, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  output logic irq_o,                               // IRQ_STATUS & IRQ_EN
  output logic run_done_o,                          // one clock: a run has finished (IRQ_STATUS[0] set)
  output logic auto_o,                              // CTRL.EN, AUTO and WRITE: a run follows every frame
  // s_axis: axis_if.monitor (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.monitor s_axis,
  // AXI4 master (a ddr_ctrl port)
  output logic [ID_W-1:0] m_axi_awid,               // write address channel
  output logic [ADDR_W-1:0] m_axi_awaddr,
  output logic [7:0] m_axi_awlen,
  output logic [2:0] m_axi_awsize,
  output logic [1:0] m_axi_awburst,
  output logic m_axi_awvalid,
  input  logic m_axi_awready,
  output logic [255:0] m_axi_wdata,                 // write data channel
  output logic [31:0] m_axi_wstrb,
  output logic m_axi_wlast,
  output logic m_axi_wvalid,
  input  logic m_axi_wready,
  input  logic [ID_W-1:0] m_axi_bid,                // write response channel
  input  logic [1:0] m_axi_bresp,
  input  logic m_axi_bvalid,
  output logic m_axi_bready,
  output logic [ID_W-1:0] m_axi_arid,               // read address channel
  output logic [ADDR_W-1:0] m_axi_araddr,
  output logic [7:0] m_axi_arlen,
  output logic [2:0] m_axi_arsize,
  output logic [1:0] m_axi_arburst,
  output logic m_axi_arvalid,
  input  logic m_axi_arready,
  input  logic [ID_W-1:0] m_axi_rid,                // read data channel
  input  logic [255:0] m_axi_rdata,
  input  logic [1:0] m_axi_rresp,
  input  logic m_axi_rlast,
  input  logic m_axi_rvalid,
  output logic m_axi_rready
);
  // register interface between the register map and the logic
  npu_regs_if u_regs_if ();

  npu_regs u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  npu #(
    .ADDR_W(ADDR_W),
    .ID_W(ID_W),
    .PE_P(PE_P),
    .PE_O(PE_O)
  ) u_core (
    .clk,
    .rst_n,
    .irq_o,
    .run_done_o,
    .auto_o,
    .s_axis,
    .m_axi_awid,
    .m_axi_awaddr,
    .m_axi_awlen,
    .m_axi_awsize,
    .m_axi_awburst,
    .m_axi_awvalid,
    .m_axi_awready,
    .m_axi_wdata,
    .m_axi_wstrb,
    .m_axi_wlast,
    .m_axi_wvalid,
    .m_axi_wready,
    .m_axi_bid,
    .m_axi_bresp,
    .m_axi_bvalid,
    .m_axi_bready,
    .m_axi_arid,
    .m_axi_araddr,
    .m_axi_arlen,
    .m_axi_arsize,
    .m_axi_arburst,
    .m_axi_arvalid,
    .m_axi_arready,
    .m_axi_rid,
    .m_axi_rdata,
    .m_axi_rresp,
    .m_axi_rlast,
    .m_axi_rvalid,
    .m_axi_rready,
    .regs(u_regs_if)
  );
endmodule
